-- +goose Up
-- SQLite schema, written to port to PostgreSQL (migrations/postgres mirrors
-- it): uuid text ids generated by the app, UTC timestamps written by the app
-- (never SQL defaults, so every value has the same format), no arrays or JSON
-- types. The driver trims trailing zeros from fractional seconds, so
-- timestamps do not compare correctly as text: queries compare them through
-- julianday(), which the PostgreSQL schema defines too.

-- notes: the example resource. Replace it with your own.
CREATE TABLE notes (
    id         TEXT PRIMARY KEY,
    title      TEXT NOT NULL UNIQUE,
    body       TEXT NOT NULL DEFAULT '',
    pinned     BOOLEAN NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL
);

-- +goose Down
DROP TABLE notes;
